@paginate(PAGINATION_MODEL)
def list_account_assignments_for_principal(
    self, instance_arn: str, principal_id: str, principal_type: str, filter_dict: Dict[str, str] = None
) -> List[Dict[str, str]]:
    """
    List account assignments for a specific principal (user or group).

    Args:
        instance_arn: The ARN of the SSO instance.
        principal_id: The ID of the principal.
        principal_type: The type of the principal (USER or GROUP).
        filter_dict: Optional filter dictionary, can contain AccountId.

    Returns:
        A list of account assignments for the specified principal.
    """
    # Validate principal_type
    if principal_type not in ["USER", "GROUP"]:
        raise ValueError(
            f"Invalid PrincipalType: {principal_type}. Valid values are: USER, GROUP"
        )

    # Validate instance_arn
    instance_exists = False
    for instance in self.instances:
        if instance.instance_arn == instance_arn:
            instance_exists = True
            break

    if not instance_exists and self.instances:
        raise ResourceNotFoundException(f"Instance not found: {instance_arn}")

    account_assignments = []
    account_id = None

    # Validate and extract filter parameters
    if filter_dict:
        # Only AccountId is supported in the filter
        valid_filter_keys = ["AccountId"]
        for key in filter_dict:
            if key not in valid_filter_keys:
                raise ValueError(
                    f"Invalid filter key: {key}. Valid filter keys are: {', '.join(valid_filter_keys)}"
                )

        if "AccountId" in filter_dict:
            account_id = filter_dict["AccountId"]

    # Find matching assignments
    for assignment in self.account_assignments:
        if (
            assignment.instance_arn == instance_arn
            and assignment.principal_id == principal_id
            and assignment.principal_type == principal_type
            and (account_id is None or assignment.target_id == account_id)
        ):
            account_assignments.append(
                {
                    "AccountId": assignment.target_id,
                    "PermissionSetArn": assignment.permission_set_arn,
                    "PrincipalType": assignment.principal_type,
                    "PrincipalId": assignment.principal_id,
                }
            )
    return account_assignments

